import{_ as t,o as i,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-09-28","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-09-28","date":"2021-09-28T00:00:00.000Z","updated":"2021-10-08T00:00:00.000Z","tags":["Ceph","Orchestrator","Storage Classes","Rook","IPVS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-28.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-09-28.md","lastUpdated":1780460162000}'),e={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-09-28.md"};function a(s,l,n,u,h,g){return i(),o("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2021-09-28</li><li><strong>参与者</strong>: [参与者名单]</li><li><strong>主持人</strong>: [主持人姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Rook和存储类（Storage Classes）</strong></p><ul><li><strong>讨论内容</strong>: <ul><li>需要创建支持存储类的OSD（Object Storage Daemon）。</li><li>讨论了如何在Rook中实现存储类，包括在CRD（Custom Resource Definition）中的存储部分设置存储类。</li></ul></li><li><strong>决定事项</strong>: <ul><li>需要一个新的Orchestrator API来列出集群中可用的存储类。</li><li>需要在驱动组属性中添加存储类。</li></ul></li><li><strong>后续行动</strong>: <ul><li>开发新的Orchestrator API。</li><li>与Dashboard团队讨论如何在界面上展示存储类。</li></ul></li></ul></li><li><p><strong>Rook与Ceph的兼容性测试</strong></p><ul><li><strong>讨论内容</strong>: <ul><li>过去一年中，Ceph的某些更改导致Rook出现问题。</li><li>需要确保Ceph发布前能够进行Rook的兼容性测试。</li></ul></li><li><strong>决定事项</strong>: <ul><li>请求在Ceph发布前进行Rook的兼容性测试。</li></ul></li><li><strong>后续行动</strong>: <ul><li>与Ceph团队沟通，确保Rook的兼容性测试纳入Ceph的发布流程。</li></ul></li></ul></li><li><p><strong>HAProxy与IPVS</strong></p><ul><li><strong>讨论内容</strong>: <ul><li>讨论了使用IPVS作为L4负载均衡器的可行性，以提高读取流量的可扩展性。</li><li>讨论了IPVS的直接服务器返回（DSR）功能及其在不同网络环境下的应用。</li></ul></li><li><strong>决定事项</strong>: <ul><li>将IPVS作为L4负载均衡选项纳入考虑。</li></ul></li><li><strong>后续行动</strong>: <ul><li>进一步研究IPVS的实现细节，并在后续版本中考虑实施。</li></ul></li></ul></li><li><p><strong>未来规划</strong></p><ul><li><strong>讨论内容</strong>: <ul><li>讨论了Ceph的未来版本（如Quincy）的规划和需求。</li></ul></li><li><strong>决定事项</strong>: <ul><li>需要进一步讨论和规划Ceph的未来版本。</li></ul></li><li><strong>后续行动</strong>: <ul><li>在Trello板上添加相关议题，以便后续讨论。</li></ul></li></ul></li></ol><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>会议记录</strong>: <ul><li>会议记录已添加到会议材料中。</li></ul></li><li><strong>下次会议</strong>: <ul><li>下次会议将在下周举行。</li></ul></li></ul><h4 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h4><ul><li>开发新的Orchestrator API以支持存储类。</li><li>与Ceph团队沟通，确保Rook的兼容性测试纳入Ceph的发布流程。</li><li>进一步研究IPVS的实现细节，并在后续版本中考虑实施。</li><li>在Trello板上添加相关议题，以便后续讨论。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>时间</strong>: [具体结束时间]</li><li><strong>下次会议</strong>: [下次会议的具体日期和时间]</li></ul>',11)])])}const d=t(e,[["render",a]]);export{c as __pageData,d as default};
